        return

    last_line = lines[-1]  # most recent last
    # Expected format: ORD-XXXX
    suffix = last_line.split('-')[1]
    next_suffix = base36_increment(suffix)
    print(f'ORD-{next_suffix}')

if __name__ == '__main__':
    main()

