#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import os

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def base36_encode(n: int, width: int = 4) -> str:
    """Encode integer n as a base-36 string padded to width characters."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def main() -> None:
    script_dir = os.path.dirname(os.path.abspath(__file__))
    ids_path = os.path.join(script_dir, "ids.txt")

    last_id = None
    with open(ids_path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split("\t")
            # Format: "1\tORD-XXXX"
            if len(parts) == 2:
                candidate = parts[1].strip()
            else:
                candidate = parts[0]
            if candidate.startswith("ORD-"):
                last_id = candidate

    if last_id is None:
        next_code = "0000"
    else:
        suffix = last_id[4:]  # e.g. "243G"
        current = base36_decode(suffix)
        next_code = base36_encode(current + 1)

    print(f"ORD-{next_code}")


if __name__ == "__main__":
    main()

