import sys

def to_base36(num, width=4):
    """Convert a number to a zero-padded base-36 string of given width."""
    digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    for _ in range(width):
        result = digits[num % 36] + result
        num //= 36
    return result

def from_base36(s):
    """Convert a base-36 string to a number."""
    return int(s, 36)

def main():
    try:
        with open('ids.txt', 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        # No ids.txt yet; start with the first id
        next_num = 0
    else:
        # Filter out empty lines
        lines = [line.strip() for line in lines if line.strip()]
        if not lines:
            next_num = 0
        else:
            last_line = lines[-1]
            # Extract the 4-character code after "ORD-"
            code = last_line.split('ORD-')[-1].strip()
            next_num = from_base36(code) + 1

    next_id = 'ORD-' + to_base36(next_num)
    sys.stdout.write(next_id + '\n')

if __name__ == '__main__':
    main()

