import sys

ID_FILE = "ids.txt"


def base36_encode(n: int) -> str:
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def base36_decode(s: str) -> int:
    return int(s, 36)


def main() -> None:
    try:
        with open(ID_FILE) as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    # Most recent (highest) id is last line
    last_id = lines[-1]
    prefix, suffix = last_id.split("-", 1)
    current_num = base36_decode(suffix)
    next_num = current_num + 1
    next_suffix = base36_encode(next_num).zfill(4)
    print(f"{prefix}-{next_suffix}")


if __name__ == "__main__":
    main()

