import sys


def to_base36_char(n: int) -> str:
    """Convert 0-35 to a base36 character."""
    if n < 10:
        return chr(ord("0") + n)
    return chr(ord("A") + n - 10)


def base36_to_int(s: str) -> int:
    """Parse a base36 string to integer."""
    n = 0
    for c in s:
        if "0" <= c <= "9":
            n = n * 36 + (ord(c) - ord("0"))
        elif "A" <= c <= "Z":
            n = n * 36 + (ord(c) - ord("A") + 10)
        elif "a" <= c <= "z":
            n = n * 36 + (ord(c) - ord("a") + 10)
        else:
            raise ValueError(f"Invalid base36 character: {c!r}")
    return n


def format_base36(n: int, width: int) -> str:
    """Format integer as a zero-padded base36 string of the given width."""
    chars = []
    for _ in range(width):
        chars.append(to_base36_char(n % 36))
        n //= 36
    if n != 0:
        raise ValueError("Value too large for the given width")
    return "".join(reversed(chars))


def next_id(last_id: str) -> str:
    prefix = "ORD-"
    if not last_id.startswith(prefix):
        raise ValueError(f"Id does not start with {prefix!r}: {last_id!r}")
    suffix = last_id[len(prefix):]
    n = base36_to_int(suffix)
    return prefix + format_base36(n + 1, len(suffix))


