#!/usr/bin/env python3
"""Read ids.txt (one order id per line, most recent last) and print the next order id."""

import sys

BASE = 36
DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
WIDTH = 4


def decode(s: str) -> int:
    n = 0
    for ch in s:
        n = n * BASE + DIGITS.index(ch)
    return n


def encode(n: int) -> str:
    chars = []
    for _ in range(WIDTH):
        chars.append(DIGITS[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last = lines[-1]
    prefix = "ORD-"
    if not last.startswith(prefix) or len(last) != len(prefix) + WIDTH:
        print(f"unexpected id format: {last!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last[len(prefix):]
    n = decode(suffix) + 1
    next_id = f"{prefix}{encode(n)}"
    print(next_id)


if __name__ == "__main__":
    main()

