import sys

def increment_id(suffix: str) -> str:
    """Increment a 4-character base-36 string."""
    chars = list(suffix)
    for i in range(3, -1, -1):
        c = chars[i]
        if '0' <= c <= '8':
            chars[i] = chr(ord(c) + 1)
            break
        elif c == '9':
            chars[i] = 'A'
            break
        elif 'A' <= c <= 'Y':
            chars[i] = chr(ord(c) + 1)
            break
        elif c == 'Z':
            chars[i] = '0'
            # continue loop to carry over
        else:
            raise ValueError(f"Unexpected character: {c}")
    else:
        raise OverflowError("ID overflow (all ZZZZ)")
    return ''.join(chars)

def main():
    with open('ids.txt') as f:
        lines = f.readlines()
    # Find the last non-empty line
    last_line = ''
    for line in reversed(lines):
        line = line.strip()
        if line:
            last_line = line
            break
    if not last_line:
        print("ORD-0000")
        return
    prefix, suffix = last_line.split('-')
    next_suffix = increment_id(suffix)
    print(f"{prefix}-{next_suffix}")

if __name__ == '__main__':
    main()

