#!/usr/bin/env python3
import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Compute SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            block = f.read(65536)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    if not os.path.isdir(RELEASE_DIR):
        print(f"Error: '{RELEASE_DIR}' directory not found.")
        return

    for root, dirs, files in os.walk(RELEASE_DIR):
        for filename in sorted(files):
            full_path = os.path.join(root, filename)
            # Normalize path separators to forward slashes for consistency
            relative = os.path.relpath(full_path).replace(os.sep, "/")
            manifest[relative] = sha256_digest(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Written {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

