#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of the file at *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def build_manifest() -> dict[str, str]:
    """Walk release/ and return {relative_path: sha256_hex}."""
    manifest: dict[str, str] = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel] = sha256_hex(path)
    return manifest


def main() -> None:
    manifest = build_manifest()
    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

