#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    """Return the hex SHA-256 digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}

    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if not fpath.is_file():
            continue
        # Store the path relative to the repository root, using forward slashes
        rel = str(fpath.relative_to(RELEASE_DIR.parent).as_posix())
        manifest[rel] = sha256_digest(fpath)

    with open(MANIFEST_PATH, "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

