#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of the file at *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        raise SystemExit(f"error: {RELEASE_DIR} does not exist")

    manifest = {}

    for p in sorted(RELEASE_DIR.rglob("*")):
        if p.is_file():
            # Relative path with forward slashes (e.g. "release/app/main.py")
            rel = str(p.relative_to(RELEASE_DIR.parent).as_posix())
            manifest[rel] = sha256_digest(p)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

