import os
import re


def report_sort_key(filename: str) -> int:
    """Extract numeric suffix from report-<n>.txt for sorting."""
    m = re.search(r"report-(\d+)\.txt$", filename)
    if m is None:
        return -1
    return int(m.group(1))


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    try:
        names = os.listdir(reports_dir)
    except FileNotFoundError:
        return

    reports = [n for n in names if re.match(r"report-\d+\.txt$", n)]
    reports.sort(key=report_sort_key)

    for r in reports:
        print(r)


if __name__ == "__main__":
    main()

