#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(__file__), "reports")


def report_key(name: str) -> int:
    """Extract the numeric part of a report filename for sorting."""
    m = re.search(r"report-(\d+)\.txt$", name)
    if m is None:
        raise ValueError(f"Unexpected filename: {name}")
    return int(m.group(1))


def main() -> None:
    if not os.path.isdir(REPORTS_DIR):
        print("reports/ directory not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    names = sorted(os.listdir(REPORTS_DIR), key=report_key)
    for name in names:
        print(name)


if __name__ == "__main__":
    main()

