#!/usr/bin/env python3
"""Print report file names in report order."""

import glob
import re


def report_key(filename: str) -> int:
    """Extract the numeric report number from a filename like report-3.txt."""
    match = re.search(r"report-(\d+)", filename)
    if match is None:
        return 0
    return int(match.group(1))


def main() -> None:
    reports = sorted(glob.glob("reports/report-*.txt"), key=report_key)
    for path in reports:
        # Print just the file name, not the full path
        print(path.removeprefix("reports/"))


if __name__ == "__main__":
    main()

