#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_sort_key(name: str) -> int:
    """Extract the numeric suffix from 'report-<n>.txt' for sorting."""
    m = re.search(r"report-(\d+)\.txt$", name)
    return int(m.group(1)) if m else -1


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = [e for e in entries if re.match(r"report-\d+\.txt$", e)]
    reports.sort(key=report_sort_key)

    for r in reports:
        print(r)


if __name__ == "__main__":
    main()

