"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"

def report_sort_key(filename: str) -> int:
    """Extract the numeric portion from a filename like report-42.txt."""
    m = re.search(r"report-(\d+)", filename)
    if not m:
        return 0  # fallback for unexpected names
    return int(m.group(1))

def main() -> None:
    try:
        files = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: {REPORTS_DIR}/ not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    reports = sorted(
        (f for f in files if f.startswith("report-") and f.endswith(".txt")),
        key=report_sort_key,
    )
    for r in reports:
        print(r)

if __name__ == "__main__":
    main()

