#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(filename: str) -> int:
    """Extract the numeric part from a report filename for sorting."""
    match = re.search(r"report-(\d+)", filename)
    if match:
        return int(match.group(1))
    return 0


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found")
        return

    report_files = [f for f in entries if f.startswith("report-") and f.endswith(".txt")]
    report_files.sort(key=report_key)

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

