"""Print report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"

def report_key(filename: str) -> int:
    """Extract the numeric part from a report-<n>.txt filename."""
    m = re.match(r"report-(\d+)\.txt", filename)
    if m:
        return int(m.group(1))
    return -1  # non-matching files sort before all reports

def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = [e for e in entries if re.match(r"report-\d+\.txt", e)]
    reports.sort(key=report_key)

    for r in reports:
        print(r)

if __name__ == "__main__":
    main()

