#!/usr/bin/env python3
"""Rotate old entries from app.log to archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading YYYY-MM-DD HH:MM:SS from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_dt = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    with open("app.log") as f:
        lines = f.readlines()

    old_lines: list[str] = []
    new_lines: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None:
            dt_utc = dt.replace(tzinfo=timezone.utc)
            if dt_utc < cutoff_dt:
                old_lines.append(line)
            else:
                new_lines.append(line)
        else:
            # Keep lines that don't match the expected format (defensive)
            new_lines.append(line)

    if old_lines:
        with open("archive.log", "a") as f:
            f.writelines(old_lines)

    with open("app.log", "w") as f:
        f.writelines(new_lines)


if __name__ == "__main__":
    main()

