"""Rotate entries older than 7 days before AS_OF from app.log to archive.log."""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    for line in lines:
        # Preserve empty lines as-is at end of file
        if not line.strip():
            keep.append(line)
            continue

        ts = parse_timestamp(line)
        if ts is None:
            keep.append(line)
            continue

        line_ts = int(ts.timestamp())
        if line_ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Write archive.log (append mode)
    with open("archive.log", "a") as f:
        for line in archive:
            f.write(line)

    # Rewrite app.log
    with open("app.log", "w") as f:
        for line in keep:
            f.write(line)


if __name__ == "__main__":
    main()

