#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log.

Usage: python rotate.py AS_OF
"""

import sys
from datetime import datetime, timedelta, timezone


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    # Threshold: 7 days before AS_OF (strictly older means < threshold)
    threshold_dt = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    old_entries = []  # entries to move to archive.log
    new_entries = []  # entries to keep in app.log

    with open("app.log", "r") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line.strip():
                # Preserve blank lines in-place (keep in app.log, not archive)
                new_entries.append(line)
                continue

            # Parse the leading timestamp: YYYY-MM-DD HH:MM:SS
            try:
                ts_str = line[:19]
                entry_dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S").replace(
                    tzinfo=timezone.utc
                )
            except ValueError:
                # Lines that don't start with a valid timestamp stay in app.log
                new_entries.append(line)
                continue

            if entry_dt < threshold_dt:
                old_entries.append(line)
            else:
                new_entries.append(line)

    # Append old entries to archive.log, preserving order
    if old_entries:
        with open("archive.log", "a") as f:
            for entry in old_entries:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries, preserving order
    with open("app.log", "w") as f:
        for entry in new_entries:
            if entry == "":
                f.write("\n")
            else:
                f.write(entry + "\n")


if __name__ == "__main__":
