        else:
            kept.append(stripped)

    if moved:
        with open("archive.log", "a") as f:
            f.write("\n".join(moved) + "\n")

    with open("app.log", "w") as f:
        if kept:
            f.write("\n".join(kept) + "\n")


if __name__ == "__main__":
