import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str):
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    # Read current app.log
    with open("app.log", "r") as f:
        lines = f.readlines()

    # Preserve trailing newlines but skip truly empty trailing lines for splitting
    # We'll keep track of the original content precisely
    keep = []
    move = []

    for line in lines:
        # Skip empty lines (they don't contain entries)
        if line.strip() == "":
            continue

        entry_dt = parse_timestamp(line)
        if entry_dt is None:
            # If we can't parse the timestamp, keep the line (don't discard data)
            keep.append(line)
        elif entry_dt < cutoff:
            move.append(line)
        else:
            keep.append(line)

    # Read existing archive.log entries
    existing_archive = []
    try:
        with open("archive.log", "r") as f:
            existing_archive = f.readlines()
    except FileNotFoundError:
        pass

    # Filter out empty lines from existing archive too
    existing_archive = [l for l in existing_archive if l.strip() != ""]

    # Write archive.log: existing entries first, then newly moved entries (preserving order)
    with open("archive.log", "w") as f:
        for line in existing_archive:
            f.write(line.rstrip("\n") + "\n")
        for line in move:
            f.write(line.rstrip("\n") + "\n")

    # Write app.log with remaining entries
    with open("app.log", "w") as f:
        for line in keep:
            f.write(line.rstrip("\n") + "\n")

    print(f"Rotated {len(move)} entries to archive.log, kept {len(keep)} in app.log")


if __name__ == "__main__":
    main()

