"""Rotate log entries from app.log to archive.log based on age relative to AS_OF."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    kept: list[str] = []
    archived: list[str] = []

    for line in lines:
        # Preserve empty lines and unparseable lines — keep them in app.log
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archived.append(line)
        else:
            kept.append(line)

    with open("app.log", "w") as f:
        f.writelines(kept)

    if archived:
        with open("archive.log", "a") as f:
            f.writelines(archived)


if __name__ == "__main__":
    main()

